private static void iteratedPostOrder() {
    if (topNode == null || topNode.getValue() == null) {
        System.out.println("空二叉树！请输入数据！");
        return;
    }
    Stack stack = new Stack();
    TreeNode node = topNode;
    while(node != null || !stack.isEmpty()) {
        if (node != null) {
            node.setFlag(1);
            stack.push(node);
            node = node.getLeftNode();
        } else {
            while(!stack.isEmpty() && stack.getTop().getFlag() == 2) {
                TreeNode tempNode = stack.pop();
                if (tempNode.getValue() != null) {
                    System.out.print(tempNode.getValue() + " ");
                }
            }
            if (!stack.isEmpty()) {
                stack.getTop().setFlag(2);
                node = stack.getTop().getRightNode();
            }
        }
    }
}

private static void judgeTree() {
    if (topNode == null || topNode.getValue() == null) {
        System.out.println("空二叉树！请输入数据！");
        return;
    }
    Queue queue = new Queue();
    queue.enQueue(topNode);
    while(!queue.isEmpty()) {
        TreeNode node = queue.getFirst();
        boolean hasLeft = node.getLeftNode() != null && node.getLeftNode().getValue() != null;
        boolean hasRight = node.getRightNode() != null && node.getRightNode().getValue() != null;
        if (hasLeft && hasRight) {
            queue.deQueue();
            queue.enQueue(node.getLeftNode());
            queue.enQueue(node.getRightNode());
        } else if (!hasLeft && hasRight) {
            System.out.println("该树不是完全二叉树！");
            return;
        } else {
            queue.deQueue();
            while(!queue.isEmpty()) {
                node = queue.getFirst();
                if ((node.getLeftNode() != null && node.getLeftNode().getValue() != null)
                        || (node.getRightNode() != null && node.getRightNode().getValue() != null)) {
                    System.out.println("该树不是完全二叉树！");
                    return;
                }
                queue.deQueue();
            }
            System.out.println("该树是完全二叉树！");
            return;
        }
    }
    System.out.println("该树是完全二叉树！");
}

